-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_HTB.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/London'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_HTB.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_HTB.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: September GL, loans and savings
SELECT SYSTEM$STREAM_HAS_DATA('SDP_HTB.PUBLIC.STR_GL_JOURNAL') OR SYSTEM$STREAM_HAS_DATA('SDP_HTB.PUBLIC.STR_LOAN_LEDGER');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_HTB.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-09';
-- step 3 · Fallback: paged extract from ledger replica
CALL SDP_HTB.SNOWBOTS.SP_BACKFILL_FROM_REPLICA('LOAN_LEDGER', '2026-09', page_size => 5000);
-- step 4 · Reconcile: interest accruals, savings and intercompany
CALL SDP_HTB.SNOWBOTS.SP_RECONCILE(period => '2026-09', tolerance_pct => 0.5);
-- step 5 · Guardrail: completeness ≥ 98% and TB difference = 0
SELECT MIN(completeness) >= 0.98 AND ABS(SUM(tb_diff)) = 0 FROM SDP_HTB.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-09';
-- step 6 · Lock period 2026-09 (awaiting approval)
CALL SDP_HTB.PUBLIC.SP_LOCK_PERIOD('2026-09', approved_by => :approver);

