-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_HTB.SNOWBOTS.T_DRIVER_REFRESH
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/London'
  CONFIG = '{"autonomy": 4}'
AS
  CALL SDP_HTB.SNOWBOTS.SP_RUN_BOT('driver-refresh');

-- step 1 · Marketplace share refreshed
SELECT MAX(date) FROM RATES_MARKETPLACE.PUBLIC.GBP_CURVES_DAILY;
-- step 2 · Upsert rate drivers
MERGE INTO SDP_HTB.PUBLIC.DIM_RATE_DRIVER t USING (SELECT * FROM RATES_MARKETPLACE.PUBLIC.GBP_CURVES_DAILY WHERE date = CURRENT_DATE - 1) s ON t.tenor = s.tenor ...;
-- step 3 · Guardrail: daily move ≤ 25 bp
SELECT MAX(ABS(bp_change)) <= 25 FROM SDP_HTB.SNOWBOTS.V_RATE_MOVES;
-- step 4 · Recalculate funding cost and NII for Oct–Dec
CALL SDP_HTB.PUBLIC.SP_RECALC(scope => 'NII', from_period => '2026-10');
-- step 5 · One-line impact note
SELECT AI_COMPLETE('claude-sonnet-4-5', 'One sentence on: ' || :impact_json);

